"""Exception definitions."""

import typing

from jsilib import _utils, exc

__all__ = export = _utils.ExportList()


@export
class JSONRPCError(exc.JSILIBError):
    """Base class for JSONRPC-specific exceptions."""


@export
class MessageError(JSONRPCError):
    """Base class for message errors."""
    __message_template__: str = '{self.message}'

    def __init__(self, message: str):
        super().__init__()
        self._message = message

    @property
    def message(self) -> str:
        return self._message


@export
class MessageParsingError(MessageError):
    """Raised when parsing of a received JSONRPC message fails.

    This may happen f.e. if JSON object sent by peer is malformed and cannot be
    parsed into a Python dict object.
    """


@export
class MessageValidationError(MessageError):
    """Raised when received message is not a valid JSONRPC message."""

    def __init__(self, message: str, errors: typing.Dict[str, str] = None):
        super().__init__(message)
        self._errors = errors

    @property
    def __message_template__(self) -> str:
        if self.errors is not None:
            return '{self.message}: {self.errors!r}'
        return '{self.message}'

    @property
    def errors(self) -> typing.Optional[typing.Dict[str, str]]:
        return self._errors


@export
class ClientClosedError(JSONRPCError):
    """Raised when client is performing operations after it was closed.

    Additionally, this exception will be raised by blocked
    :meth:`IJSONRPCClient.execute` methods after client is closed.
    """
